class Solution:
    def numberOfSequence(self, n: int, sick: List[int]) -> int:
        MOD = 10**9 + 7
        sick_set = set(sick)
        intervals = []
        start = 0
        for pos in sorted(sick):
            if start < pos:
                intervals.append((start, pos - 1))
            start = pos + 1
        if start < n:
            intervals.append((start, n - 1))

        total = 1
        for (l, r) in intervals:
            length = r - l + 1
            if length == 0:
                continue
            total = (total * self.count_sequences(length)) % MOD
        return total

    def count_sequences(self, length: int) -> int:
        MOD = 10**9 + 7
        if length == 1:
            return 1
        dp = [0] * (length + 1)
        dp[1] = 1
        dp[2] = 2
        for i in range(3, length + 1):
            dp[i] = (dp[i-1] + dp[i-2]) % MOD
        return dp[length]
